viz.option:
option = {
  title: {
    text: 'Infrastructure Cost Breakdown ($K)',
    left: 'center'
  },
  tooltip: {
    formatter: '{b}: ${c}K'
  },
  series: [
    {
      name: 'Infrastructure',
      type: 'treemap',
      visibleMin: 300,
      label: {
        show: true,
        formatter: '{b}\n${c}K'
      },
      upperLabel: {
        show: true,
        height: 28,
        color: '#fff'
      },
      itemStyle: {
        borderColor: '#fff',
        borderWidth: 2
      },
      levels: [
        {
          itemStyle: {
            borderWidth: 3,
            borderColor: '#333',
            gapWidth: 3
          }
        },
        {
          colorSaturation: [0.35, 0.5],
          itemStyle: {
            borderColorSaturation: 0.6,
            gapWidth: 1,
            borderWidth: 2
          }
        }
      ],
      data: [
        {
          name: 'Compute',
          value: 450,
          children: [
            { name: 'Web Servers', value: 180 },
            { name: 'App Servers', value: 150 },
            { name: 'Batch Jobs',  value: 120 }
          ]
        },
        {
          name: 'Database',
          value: 340,
          children: [
            { name: 'Primary DB',     value: 180 },
            { name: 'Read Replicas',  value: 100 },
            { name: 'Cache Layer',    value: 60  }
          ]
        },
        {
          name: 'Storage',
          value: 280,
          children: [
            { name: 'Block Storage',   value: 120 },
            { name: 'Object Storage',  value: 100 },
            { name: 'Backups',         value: 60  }
          ]
        },
        {
          name: 'Networking',
          value: 160,
          children: [
            { name: 'CDN',             value: 80 },
            { name: 'Load Balancers',  value: 50 },
            { name: 'Egress Bandwidth',value: 30 }
          ]
        },
        {
          name: 'Monitoring',
          value: 95,
          children: [
            { name: 'APM',     value: 50 },
            { name: 'Logging', value: 30 },
            { name: 'Tracing', value: 15 }
          ]
        }
      ]
    }
  ]
};

